<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {generatePractice,getModelSettings,getPracticeSession,listBases,listDocuments,listPracticeSessions,previewDocument,reviewPractice,submitPractice,gradePendingPractice,type PracticeQuestionType,type PracticeSession} from '../api/client'

const bases=ref<any[]>([]),kb=ref(''),documents=ref<any[]>([]),documentIds=ref<string[]>([]),allDocuments=ref(true),history=ref<any[]>([])
const questionTypes=ref<PracticeQuestionType[]>(['SINGLE_CHOICE','TRUE_FALSE','SHORT_ANSWER']),difficulty=ref<'EASY'|'MEDIUM'|'HARD'>('MEDIUM'),questionCount=ref(6)
const session=ref<PracticeSession|null>(null),answers=ref<Record<string,string>>({}),result=ref<any|null>(null),loading=ref(false),error=ref(''),notice=ref(''),generationProvider=ref('OLLAMA'),preview=ref(''),previewTitle=ref('')
const canSubmit=computed(()=>!!session.value&&session.value.status==='IN_PROGRESS'&&session.value.questions.every(q=>(answers.value[q.id]||'').trim().length>0))
const canGenerate=computed(()=>!loading.value&&!!kb.value&&documents.value.length>0&&(allDocuments.value||documentIds.value.length>0)&&questionTypes.value.length>0&&questionCount.value>=questionTypes.value.length&&questionCount.value<=20)
function val(x:any,k:string){return x?.[k]??x?.[k.toUpperCase()]}
function toggleAllDocuments(event:Event){const checked=(event.target as HTMLInputElement).checked;allDocuments.value=checked;documentIds.value=checked?[]:documents.value.map(d=>String(val(d,'id')))}
function selectDocument(){allDocuments.value=false}
function formatOptions(options:string[]){return options.map((o,i)=>`${String.fromCharCode(65+i)}. ${o}`).join('　')}
async function refreshGenerationProvider(){try{const settings=await getModelSettings();generationProvider.value=settings.generation.provider;return settings.generation.provider}catch(e:any){error.value=e.message||'无法读取当前生成模型设置';return null}}
async function confirmShortAnswerDisclosure(action:'submit'|'retry'){const provider=await refreshGenerationProvider();if(!provider)return false;if(provider!=='OPENAI_COMPATIBLE')return true;const verb=action==='submit'?'提交后将':'重试评分时将';return window.confirm(`当前生成模型使用兼容公共 API，${verb}发送简答题的题干、参考答案、解析和你的作答，用于辅助评分。是否继续？`)}
async function loadHistory(){if(!kb.value)return;history.value=(await listPracticeSessions(kb.value)).items||[]}
async function selectBase(){session.value=null;result.value=null;answers.value={};documentIds.value=[];allDocuments.value=true;error.value='';try{const [d]=await Promise.all([listDocuments(kb.value),loadHistory()]);documents.value=(d.items||[]).filter((x:any)=>val(x,'status')==='READY')}catch(e:any){error.value=e.message}}
async function generate(){if(!kb.value)return;if(!allDocuments.value&&!documentIds.value.length){error.value='自选范围至少保留一份资料';return}if(questionTypes.value.length===0||questionCount.value<questionTypes.value.length||questionCount.value>20){error.value='至少选择一种题型，题数须为所选题型数量至 20';return}const provider=await refreshGenerationProvider();if(!provider)return;if(provider==='OPENAI_COMPATIBLE'&&!window.confirm('本次所选资料片段会发送给兼容公共 API 生成练习题。继续吗？'))return
  loading.value=true;error.value='';notice.value='';result.value=null;try{session.value=await generatePractice({knowledgeBaseId:kb.value,documentIds:documentIds.value,questionTypes:questionTypes.value,difficulty:difficulty.value,questionCount:Number(questionCount.value)});answers.value={};await loadHistory();notice.value='练习已生成，提交前不会提供答案和解析'}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function submit(){if(!session.value||!canSubmit.value)return;if(session.value.questions.some(q=>q.type==='SHORT_ANSWER')&&!(await confirmShortAnswerDisclosure('submit')))return;loading.value=true;error.value='';try{result.value=await submitPractice(session.value.id,session.value.questions.map(q=>({questionId:q.id,answer:answers.value[q.id]})));session.value=await getPracticeSession(session.value.id);await loadHistory();notice.value=result.value.scoringPending?'作答已保存，简答题评分暂不可用，可稍后重试':'作答已保存，可查看答案、解析和资料来源'}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function openHistory(item:any){loading.value=true;error.value='';try{if(item.status==='SUBMITTED'){result.value=await reviewPractice(item.id);session.value=await getPracticeSession(item.id);answers.value={}}else{session.value=await getPracticeSession(item.id);result.value=null;answers.value={}}}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function retryGrade(){if(!session.value)return;const needsShortGrade=result.value?.questions?.some((q:any)=>q.type==='SHORT_ANSWER'&&q.scoringStatus!=='GRADED');if(needsShortGrade&&!(await confirmShortAnswerDisclosure('retry')))return;loading.value=true;error.value='';try{result.value=await gradePendingPractice(session.value.id);notice.value=result.value.scoringPending?'仍有简答题等待评分':'简答题辅助评分已完成';await loadHistory()}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function openSource(source:any){previewTitle.value=`${source.documentName} · ${source.location}`;try{if(source.available===false||!source.documentId){preview.value=`资料当前不可用，以下为出题时保存的摘录：\n\n${source.excerpt||''}`;return}const r=await previewDocument(source.documentId);preview.value=(r.text||source.excerpt||'').slice(0,9000)}catch{preview.value=`资料预览不可用，以下为出题时保存的摘录：\n\n${source.excerpt||''}`}}
onMounted(async()=>{try{const [b,m]=await Promise.all([listBases(),getModelSettings()]);bases.value=b.items||[];generationProvider.value=m.generation.provider;if(bases.value.length){kb.value=String(val(bases.value[0],'id'));await selectBase()}}catch(e:any){error.value=e.message}})
</script>

<template>
  <section class="practice-page">
    <div class="study-heading"><div><p class="eyebrow">PRACTICE & FEEDBACK</p><h2>练习与反馈</h2><p class="muted">按资料范围生成题目；提交后显示答案与解析。</p></div><label>知识库<select v-model="kb" @change="selectBase"><option v-for="b in bases" :key="val(b,'id')" :value="val(b,'id')">{{val(b,'name')}}</option></select></label></div>
    <p v-if="error" class="error">{{error}}</p><p v-if="notice" class="success">{{notice}}</p>
    <div v-if="!bases.length" class="card">请先创建知识库并导入资料。</div>
    <div v-else class="practice-grid">
      <section class="card practice-config"><h3>练习设置</h3><fieldset><legend>资料范围</legend><label class="check-row"><input type="checkbox" :checked="allDocuments" @change="toggleAllDocuments" />全部已索引资料</label><label v-for="d in documents" :key="val(d,'id')" class="check-row"><input v-model="documentIds" type="checkbox" :value="val(d,'id')" @change="selectDocument" />{{val(d,'originalName')||val(d,'original_name')}}</label><p class="muted">{{allDocuments?'默认范围为全部已索引资料':'仅使用勾选的资料'}}</p><p v-if="!documents.length" class="muted">当前知识库没有已完成索引的资料。</p></fieldset>
        <fieldset><legend>题型</legend><label class="check-row"><input v-model="questionTypes" type="checkbox" value="SINGLE_CHOICE" />单选题</label><label class="check-row"><input v-model="questionTypes" type="checkbox" value="TRUE_FALSE" />判断题</label><label class="check-row"><input v-model="questionTypes" type="checkbox" value="SHORT_ANSWER" />简答题</label></fieldset>
        <label>难度<select v-model="difficulty"><option value="EASY">简单</option><option value="MEDIUM">中等</option><option value="HARD">困难</option></select></label><label>题目数量<input v-model.number="questionCount" type="number" min="1" max="20" /></label><button :disabled="!canGenerate" @click="generate">{{loading?'处理中…':'生成练习'}}</button>
        <h3 class="subheading">练习历史</h3><button v-for="h in history" :key="h.id" class="plan-choice" @click="openHistory(h)"><span>{{new Date(h.createdAt).toLocaleString()}} · {{h.difficulty==='EASY'?'简单':h.difficulty==='HARD'?'困难':'中等'}}</span><small>{{h.status==='SUBMITTED'?`${h.gradedCount}/${h.questionCount} 题已评分`:'未提交'}}</small></button><p v-if="!history.length" class="muted">还没有练习记录。</p>
      </section>
      <section class="card practice-content"><template v-if="result"><div class="section-title"><div><h3>作答反馈</h3><p class="muted">客观题确定性评分；简答题由模型辅助评分，单题满分 100。</p></div><strong>{{Math.round(result.score*100)}} / {{result.questionCount*100}} 分</strong></div><p v-if="result.scoringPending" class="error">简答题评分服务暂不可用，你的答案已保存。</p><article v-for="q in result.questions" :key="q.id" class="practice-question" :class="{wrong:q.score!==null&&q.score<0.5}"><span class="tag">{{q.type==='SINGLE_CHOICE'?'单选':q.type==='TRUE_FALSE'?'判断':'简答'}} · {{q.score===null?'待评分':`${Math.round(q.score*100)} 分`}}</span><h4>{{q.stem}}</h4><p v-if="q.options?.length" class="muted">{{formatOptions(q.options)}}</p><p><b>你的答案：</b>{{q.submittedAnswer}}</p><p><b>参考答案：</b>{{q.correctAnswer}}</p><p><b>解析：</b>{{q.explanation}}</p><p><b>反馈：</b>{{q.feedback||'等待辅助评分'}}</p><div class="task-meta"><button v-for="s in q.sources" :key="s.chunkId" class="source-link" @click="openSource(s)">{{s.documentName}} · {{s.location}} ↗</button></div></article><button v-if="result.scoringPending" :disabled="loading" @click="retryGrade">重试简答题评分</button></template>
        <template v-else-if="session"><div class="section-title"><h3>本次练习</h3><span class="tag">{{session.questionCount}} 题 · {{session.difficulty==='EASY'?'简单':session.difficulty==='HARD'?'困难':'中等'}}</span></div><p v-if="session.status==='SUBMITTED'" class="muted">该练习已提交。请从历史记录重新打开查看完整解析。</p><article v-for="q in session.questions" :key="q.id" class="practice-question"><span class="tag">{{q.ordinal+1}} · {{q.type==='SINGLE_CHOICE'?'单选题':q.type==='TRUE_FALSE'?'判断题':'简答题'}}</span><h4>{{q.stem}}</h4><label v-if="q.type==='SINGLE_CHOICE'" v-for="(option,index) in q.options" :key="index" class="answer-option"><input v-model="answers[q.id]" type="radio" :name="q.id" :value="String.fromCharCode(65+index)" :disabled="session.status!=='IN_PROGRESS'" />{{String.fromCharCode(65+index)}}. {{option}}</label><div v-else-if="q.type==='TRUE_FALSE'" class="answer-option"><label><input v-model="answers[q.id]" type="radio" :name="q.id" value="TRUE" :disabled="session.status!=='IN_PROGRESS'" />正确</label><label><input v-model="answers[q.id]" type="radio" :name="q.id" value="FALSE" :disabled="session.status!=='IN_PROGRESS'" />错误</label></div><textarea v-else v-model="answers[q.id]" rows="4" maxlength="5000" placeholder="填写你的答案" :disabled="session.status!=='IN_PROGRESS'"></textarea><div class="task-meta"><button v-for="s in q.sources" :key="s.chunkId" class="source-link" @click="openSource(s)">复习：{{s.documentName}} · {{s.location}}</button></div></article><button v-if="session.status==='IN_PROGRESS'" :disabled="loading||!canSubmit" @click="submit">提交并查看反馈</button></template>
        <div v-else class="empty-state">配置资料范围、题型和难度，然后生成一份练习。</div></section>
    </div>
    <div v-if="preview" class="preview-panel"><button class="close" @click="preview='';previewTitle=''">关闭</button><h3>{{previewTitle}}</h3><pre>{{preview}}</pre></div>
  </section>
</template>
